{"path":"neuron_growth_ollama-glm-4.7-flash-latest_01.html","content":"<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Neural Network Simulation</title>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/dat-gui/0.7.9/dat.gui.min.js"></script>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background-color: #05070f;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            font-family: 'Courier New', monospace;
            overflow: hidden;
        }

        #canvas-container {
            position: relative;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        canvas {
            background-color: #05070f;
            box-shadow: 0 0 50px rgba(16, 26, 58, 0.5),
                        0 0 100px rgba(0, 229, 255, 0.1);
            border-radius: 4px;
        }

        .gui-container {
            position: fixed;
            top: 10px;
            right: 10px;
            z-index: 1000;
        }

        .info-panel {
            position: fixed;
            bottom: 10px;
            left: 10px;
            color: rgba(255, 255, 255, 0.6);
            font-size: 12px;
            z-index: 1000;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="canvas-container">
        <canvas id="canvas" width="800" height="800"></canvas>
    </div>

    <div class="info-panel">
        <div>Neurons: <span id="neuron-count">0</span></div>
        <div>Branches: <span id="branch-count">0</span></div>
        <div>Synapses: <span id="synapse-count">0</span></div>
        <div>Pulses: <span id="pulse-count">0</span></div>
    </div>

    <script>
        // ===== SETUP =====
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');

        // Configuration with default neon palette values
        const config = {
            // Growth parameters
            neuronCount: 5,
            branchGrowthSpeed: 0.5,
            maxBranchDepth: 4,
            branchSplitChance: 0.15,
            branchCurvature: 0.3,
            maxBranchLength: 100,

            // Synapse parameters
            synapseDistanceThreshold: 30,
            synapseGlowStrength: 15,

            // Pulse parameters
            pulseSpeed: 3,
            pulseFrequency: 0.02,
            pulseBrightness: 1,

            // Visual parameters
            backgroundColor: '#05070f',
            branchColor: '#00e5ff',
            accentBranchColor: '#d6ff00',
            synapseColor: '#ff2bd6',
            pulseColor: '#fff36a',
            showGrid: false,
            showScanlines: false
        };

        // State storage
        let neurons = [];
        let branches = [];
        let synapses = [];
        let pulses = [];
        let isPaused = false;
        let animationId = null;

        // ===== GUI SETUP =====
        function setupGUI() {
            const gui = new dat.GUI({ autoPlace: true });

            // Growth folder
            const growthFolder = gui.addFolder('Growth');
            growthFolder.add(config, 'neuronCount', 1, 10, 1).name('Neuron Count');
            growthFolder.add(config, 'branchGrowthSpeed', 0.1, 2, 0.1).name('Growth Speed');
            growthFolder.add(config, 'maxBranchDepth', 1, 8, 1).name('Max Depth');
            growthFolder.add(config, 'branchSplitChance', 0, 0.5, 0.05).name('Split Chance');
            growthFolder.add(config, 'branchCurvature', 0, 1, 0.05).name('Curvature');
            growthFolder.add(config, 'maxBranchLength', 20, 200, 10).name('Max Length');

            // Synapses folder
            const synapseFolder = gui.addFolder('Synapses');
            synapseFolder.add(config, 'synapseDistanceThreshold', 10, 80, 5).name('Distance Threshold');
            synapseFolder.add(config, 'synapseGlowStrength', 0, 30, 1).name('Glow Strength');

            // Pulses folder
            const pulseFolder = gui.addFolder('Pulses');
            pulseFolder.add(config, 'pulseSpeed', 1, 8, 0.5).name('Pulse Speed');
            pulseFolder.add(config, 'pulseFrequency', 0.005, 0.1, 0.005).name('Frequency');
            pulseFolder.add(config, 'pulseBrightness', 0.1, 2, 0.1).name('Brightness');

            // Visuals folder
            const visualFolder = gui.addFolder('Visuals');
            visualFolder.addColor(config, 'backgroundColor').name('Background');
            visualFolder.addColor(config, 'branchColor').name('Branch');
            visualFolder.addColor(config, 'accentBranchColor').name('Accent Branch');
            visualFolder.addColor(config, 'synapseColor').name('Synapse');
            visualFolder.addColor(config, 'pulseColor').name('Pulse');
            visualFolder.add(config, 'showGrid').name('Show Grid');
            visualFolder.add(config, 'showScanlines').name('Show Scanlines');

            // Buttons
            const buttonFolder = gui.addFolder('Actions');
            buttonFolder.add({ regenerate: regenerateNetwork }, 'regenerate').name('Regenerate Network');
            buttonFolder.add({ clear: clearCanvas }, 'clear').name('Clear Canvas');
            buttonFolder.add({ togglePause: togglePause }, 'togglePause').name('Pause/Resume');

            growthFolder.open();
            synapseFolder.open();
            pulseFolder.open();
            visualFolder.open();
        }

        // ===== NEURON GROWTH =====
        class Neuron {
            constructor(x, y) {
                this.x = x;
                this.y = y;
                this.branches = [];
            }
        }

        class Branch {
            constructor(startX, startY, angle, depth, parent = null) {
                this.startX = startX;
                this.startY = startY;
                this.angle = angle;
                this.depth = depth;
                this.parent = parent;
                this.currentX = startX;
                this.currentY = startY;
                this.targetX = startX;
                this.targetY = startY;
                this.length = 0;
                this.maxLength = config.maxBranchLength;
                this.growthSpeed = config.branchGrowthSpeed;
                this.finished = false;
                this.path = [{x: startX, y: startY}];
                this.thickness = Math.max(1, (config.maxBranchDepth - depth) * 0.8);
                this.isAccent = depth === config.maxBranchDepth;
            }

            update() {
                if (this.finished) return false;

                const growth = this.growthSpeed;
                const dx = Math.cos(this.angle) * growth;
                const dy = Math.sin(this.angle) * growth;

                this.length += growth;
                this.currentX += dx;
                this.currentY += dy;

                this.path.push({x: this.currentX, y: this.currentY});

                if (this.length >= this.maxLength) {
                    this.finished = true;
                    return true;
                }

                return false;
            }

            split() {
                if (this.finished || this.depth >= config.maxBranchDepth) return null;

                if (Math.random() < config.branchSplitChance) {
                    const splitAngle = (Math.random() - 0.5) * config.branchCurvature * 2;
                    return new Branch(
                        this.currentX, 
                        this.currentY, 
                        this.angle + splitAngle, 
                        this.depth + 1, 
                        this
                    );
                }
                return null;
            }
        }

        function regenerateNetwork() {
            neurons = [];
            branches = [];
            synapses = [];
            pulses = [];

            // Generate seed neurons
            const centerX = canvas.width / 2;
            const centerY = canvas.height / 2;

            for (let i = 0; i < config.neuronCount; i++) {
                const angle = (i / config.neuronCount) * Math.PI * 2;
                const distance = 40 + Math.random() * 40;
                neurons.push(new Neuron(
                    centerX + Math.cos(angle) * distance,
                    centerY + Math.sin(angle) * distance
                ));
            }

            // Start growing branches from each neuron
            neurons.forEach(neuron => {
                const startAngle = Math.random() * Math.PI * 2;
                for (let i = 0; i < 5; i++) {
                    const branch = new Branch(
                        neuron.x,
                        neuron.y,
                        startAngle + (i * 0.5),
                        0,
                        null
                    );
                    branches.push(branch);
                }
            });
        }

        function clearCanvas() {
            neurons = [];
            branches = [];
            synapses = [];
            pulses = [];
        }

        function togglePause() {
            isPaused = !isPaused;
        }

        // ===== SYNAPSE DETECTION =====
        function detectSynapses() {
            const threshold = config.synapseDistanceThreshold;
            const newSynapses = [];

            for (let i = 0; i < branches.length; i++) {
                for (let j = i + 1; j < branches.length; j++) {
                    const b1 = branches[i];
                    const b2 = branches[j];

                    if (b1.finished && b2.finished) {
                        const dist = Math.hypot(
                            b1.currentX - b2.currentX,
                            b1.currentY - b2.currentY
                        );

                        if (dist < threshold) {
                            // Check if synapse already exists
                            const exists = synapses.some(s => 
                                (s.branch1 === b1 && s.branch2 === b2) ||
                                (s.branch1 === b2 && s.branch2 === b1)
                            );

                            if (!exists) {
                                newSynapses.push({
                                    branch1: b1,
                                    branch2: b2,
                                    strength: 1 - (dist / threshold)
                                });
                            }
                        }
                    }
                }
            }

            synapses.push(...newSynapses);
        }

        // ===== PULSE ANIMATION =====
        class Pulse {
            constructor(synapse) {
                this.synapse = synapse;
                this.progress = 0;
                this.speed = config.pulseSpeed;
                this.active = true;
            }

            update() {
                this.progress += this.speed * 0.02;

                if (this.progress >= 1) {
                    this.active = false;
                    return false;
                }

                return true;
            }

            draw(ctx) {
                const progress = this.progress;
                const b1 = this.synapse.branch1;
                const b2 = this.synapse.branch2;

                // Interpolate position
                const currentX = b1.currentX + (b2.currentX - b1.currentX) * progress;
                const currentY = b1.currentY + (b2.currentY - b1.currentY) * progress;

                // Draw pulse with glow
                ctx.save();
                ctx.shadowBlur = 10 * config.pulseBrightness;
                ctx.shadowColor = config.pulseColor;
                ctx.fillStyle = config.pulseColor;

                const size = 2 + progress * 3;
                ctx.beginPath();
                ctx.arc(currentX, currentY, size, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            }
        }

        function updatePulses() {
            // Update existing pulses
            pulses = pulses.filter(pulse => pulse.update());

            // Spawn new pulses randomly
            if (Math.random() < config.pulseFrequency && synapses.length > 0) {
                const randomSynapse = synapses[Math.floor(Math.random() * synapses.length)];
                pulses.push(new Pulse(randomSynapse));
            }
        }

        // ===== RENDERING =====
        function drawGrid() {
            if (!config.showGrid) return;

            ctx.strokeStyle = 'rgba(0, 229, 255, 0.08)';
            ctx.lineWidth = 1;

            const gridSize = 40;
            for (let x = 0; x < canvas.width; x += gridSize) {
                ctx.beginPath();
                ctx.moveTo(x, 0);
                ctx.lineTo(x, canvas.height);
                ctx.stroke();
            }

            for (let y = 0; y < canvas.height; y += gridSize) {
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(canvas.width, y);
                ctx.stroke();
            }
        }

        function drawScanlines() {
            if (!config.showScanlines) return;

            ctx.strokeStyle = 'rgba(0, 0, 0, 0.15)';
            ctx.lineWidth = 1;

            for (let y = 0; y < canvas.height; y += 3) {
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(canvas.width, y);
                ctx.stroke();
            }
        }

        function drawNeurons() {
            ctx.save();
            ctx.shadowBlur = 15;
            ctx.shadowColor = config.branchColor;
            ctx.fillStyle = config.neuronCount > 0 ? config.branchColor : '#ffffff';

            neurons.forEach(neuron => {
                ctx.beginPath();
                ctx.arc(neuron.x, neuron.y, 4, 0, Math.PI * 2);
                ctx.fill();
            });
            ctx.restore();
        }

        function drawBranches() {
            branches.forEach(branch => {
                if (branch.path.length < 2) return;

                ctx.save();
                ctx.strokeStyle = branch.isAccent ? config.accentBranchColor : config.branchColor;
                ctx.lineWidth = branch.thickness;
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';
                ctx.shadowBlur = branch.isAccent ? 12 : 6;
                ctx.shadowColor = ctx.strokeStyle;

                ctx.beginPath();
                ctx.moveTo(branch.path[0].x, branch.path[0].y);

                for (let i = 1; i < branch.path.length; i++) {
                    ctx.lineTo(branch.path[i].x, branch.path[i].y);
                }
                ctx.stroke();
                ctx.restore();
            });
        }

        function drawSynapses() {
            ctx.save();
            ctx.shadowBlur = config.synapseGlowStrength;
            ctx.shadowColor = config.synapseColor;
            ctx.fillStyle = config.synapseColor;

            synapses.forEach(synapse => {
                const size = 2 + synapse.strength * 2;
                ctx.beginPath();
                ctx.arc(synapse.branch1.currentX, synapse.branch1.currentY, size, 0, Math.PI * 2);
                ctx.fill();
            });
            ctx.restore();
        }

        function drawPulses() {
            pulses.forEach(pulse => pulse.draw(ctx));
        }

        function drawVignette() {
            const gradient = ctx.createRadialGradient(
                canvas.width / 2,
                canvas.height / 2,
                200,
                canvas.width / 2,
                canvas.height / 2,
                canvas.width / 2
            );

            gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
            gradient.addColorStop(1, 'rgba(0, 0, 0, 0.7)');

            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, canvas.width, canvas.height);
        }

        function drawBackground() {
            ctx.fillStyle = config.backgroundColor;
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Add subtle background glow
            ctx.fillStyle = 'rgba(16, 26, 58, 0.3)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
        }

        function animate() {
            if (!isPaused) {
                // Update branches
                let anyGrowing = false;
                branches.forEach(branch => {
                    if (!branch.finished) {
                        branch.update();
                        anyGrowing = true;
                    }
                });

                // Detect new synapses
                detectSynapses();

                // Update pulses
                updatePulses();
            }

            // Render
            drawBackground();
            drawGrid();
            drawBranches();
            drawSynapses();
            drawNeurons();
            drawPulses();
            drawScanlines();
            drawVignette();

            // Update info panel
            document.getElementById('neuron-count').textContent = neurons.length;
            document.getElementById('branch-count').textContent = branches.length;
            document.getElementById('synapse-count').textContent = synapses.length;
            document.getElementById('pulse-count').textContent = pulses.length;

            animationId = requestAnimationFrame(animate);
        }

        // ===== INITIALIZE =====
        function init() {
            setupGUI();
            regenerateNetwork();
            animate();
        }

        window.addEventListener('load', init);
    </script>
</body>
</html>"}
